from pathlib import Path
import ast
for path in sorted(Path('lumen').glob('*.py')):
    tree = ast.parse(path.read_text())
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            print(f'{path}:{node.lineno}-{node.end_lineno} {node.name}')
